// T143: benches of the Neo Geo core (neo_top with the vendored chip models, the DDR2 model, an application model that loads the images through the DDR2 and the register
// block the way cores/neogeo/app/lib/neogeo.cc does). The images are generated bytes (mkimg.py): a "BIOS" that sets the palette and the fix layer and jumps into the cartridge program,
// which sets up 64 overlapping sprites; no ROM, no game. One mode per run (+MODE=...); a mode ends with one PASS or FAIL line.
//   +MODE=video   run +MS machine milliseconds, print the frame hash, the stall counters and the latencies of the memory; PASS when a frame came out and its backdrop pixel is right
//   +MODE=p68k    every 68k read cycle of the system ROM and the cartridge program is compared with the image byte it must have read (the bench's own map of the 68k's address space);
//                 PASS when none differs and enough were seen
//   +DIR=<dir with the images>  +MS=<ms>  +FAST (a DDR2 that answers at once)  +LATMIN= +LATRND=
`timescale 1ns / 1ps
module tb_neo;
    reg cpu_clk = 0, ui_clk = 0, sys_clk = 0, mclk = 0;
    always #5 cpu_clk = ~cpu_clk;
    always #6.6667 ui_clk = ~ui_clk;
    always #15.86 sys_clk = ~sys_clk;
    always #40.69 mclk = ~mclk;
    reg sys_rst = 1, ui_rst = 1;

    reg  [4:0]  joy1 = 5'd0, joy2 = 5'd0;
    reg  [63:0] keys = 64'd0;
    reg         halt_req = 1'b0, reset_req = 1'b0;
    reg         cw_we = 0, cw_re = 0;
    reg  [16:0] cw_addr = 0;
    reg  [7:0]  cw_wdata = 0;
    wire [7:0]  cw_rdata;
    wire        cw_ack, cw_irq, halted, running;
    wire [26:0] c_addr, e_addr;
    wire [2:0]  c_cmd, e_cmd;
    wire        c_en, e_en, c_rdy, e_rdy, c_wdf_wren, e_wdf_wren, c_rd_valid, e_rd_valid;
    wire [127:0] c_wdf_data, e_wdf_data, rd_data;
    wire [15:0] c_wdf_mask, e_wdf_mask;
    wire signed [23:0] audio_l, audio_r;
    wire [3:0]  pix_color;
    wire [9:0]  pix_x;
    wire [8:0]  pix_y;
    neo_top dut (
        .sys_clk(sys_clk), .sys_rst(sys_rst), .cpu_clk(cpu_clk), .mclk(mclk), .ui_clk(ui_clk), .ui_rst(ui_rst),
        .reset_req(reset_req), .halt_req(halt_req), .halted(halted), .running(running),
        .dma_req_tgl(1'b0), .dma_done_tgl(), .dma_rdata(), .win_port_use(), .win_port_addr(), .win_port_rom(), .win_port_we(), .win_port_wdata(),
        .pix_color(pix_color), .pix_x(pix_x), .pix_y(pix_y),
        .c64_joy1(joy1), .c64_joy2(joy2), .c64_keys(keys),
        .audio_l(audio_l), .audio_r(audio_r),
        .cw_we(cw_we), .cw_re(cw_re), .cw_addr(cw_addr), .cw_wdata(cw_wdata), .cw_rdata(cw_rdata), .cw_ack(cw_ack), .cw_irq(cw_irq),
        .px_we(), .px_re(), .px_rdata(8'd0), .px_ev_vsync(1'b0), .px_ev_flip(1'b0), .build(32'h12345678), .ddr_cal(64'd0),
        .dbg_re(1'b0), .dbg_addr(12'd0), .j_rdata(), .j_rvalid(),
        .e_addr(e_addr), .e_cmd(e_cmd), .e_en(e_en), .e_rdy(e_rdy), .e_wdf_data(e_wdf_data), .e_wdf_mask(e_wdf_mask), .e_wdf_wren(e_wdf_wren), .e_rd_valid(e_rd_valid),
        .c_addr(c_addr), .c_cmd(c_cmd), .c_en(c_en), .c_rdy(c_rdy), .c_wdf_data(c_wdf_data), .c_wdf_mask(c_wdf_mask), .c_wdf_wren(c_wdf_wren),
        .c_rd_data(rd_data), .c_rd_valid(c_rd_valid)
    );
    neo_ddr2 dm (.ui_clk(ui_clk), .c_addr(c_addr), .c_cmd(c_cmd), .c_en(c_en), .c_rdy(c_rdy), .c_wdf_data(c_wdf_data), .c_wdf_mask(c_wdf_mask), .c_wdf_wren(c_wdf_wren), .c_rd_valid(c_rd_valid),
                 .e_addr(e_addr), .e_cmd(e_cmd), .e_en(e_en), .e_rdy(e_rdy), .e_wdf_data(e_wdf_data), .e_wdf_mask(e_wdf_mask), .e_wdf_wren(e_wdf_wren), .e_rd_valid(e_rd_valid),
                 .rd_data(rd_data));

    // ---------------------------------------------------------------- the application's bus
    task cw_wr(input [16:0] a, input [7:0] d);
        begin
            @(posedge cpu_clk); cw_addr <= a; cw_wdata <= d; cw_we <= 1'b1;
            @(posedge cpu_clk); cw_we <= 1'b0;
        end
    endtask
    reg [7:0] rd_byte;
    task cw_rd(input [16:0] a, output [7:0] d);
        begin
            @(posedge cpu_clk); cw_addr <= a; cw_re <= 1'b1;
            @(posedge cpu_clk); cw_re <= 1'b0;
            @(posedge cpu_clk); @(posedge cpu_clk); d = cw_rdata;
        end
    endtask
    task cw_wr32(input [16:0] a, input [31:0] v);
        begin
            cw_wr(a, v[7:0]); cw_wr(a + 17'd1, v[15:8]); cw_wr(a + 17'd2, v[23:16]); cw_wr(a + 17'd3, v[31:24]);
        end
    endtask
    task cw_rd32(input [16:0] a, output [31:0] v);
        reg [7:0] b0, b1, b2, b3;
        begin
            cw_rd(a, b0); cw_rd(a + 17'd1, b1); cw_rd(a + 17'd2, b2); cw_rd(a + 17'd3, b3);
            v = {b3, b2, b1, b0};
        end
    endtask

    // ---------------------------------------------------------------- images
    // REAL: a real game (mkimg is not used; tools/neogeo_layout.py image writes vspace.bin: system ROM, board fix ROM, S1, P1 and the C ROM from rom_base, 20 MB for Metal Slug)
    reg [31:0] ROM_BASE = 32'h01000000, V1_BASE = 32'h01400000, V2_BASE = 32'h01500000, M1_BASE = 32'h01600000, IMG_BASE = 32'h01700000,
               FB_BASE = 32'h01800000, FB_STRIDE = 32'h00100000;
    localparam [31:0] DDR_BASE = 32'h01000000;
    reg [7:0] filebuf [0:33554431];
    reg [7:0] vspace [0:4194303];
    string dir;
    integer fd, n, i;
    task put_ddr(input [31:0] a, input [7:0] b);
        reg [127:0] w;
        reg [21:0] wi;
        begin
            wi = (a - DDR_BASE) >> 4;
            w = dm.mem[wi];
            w[8 * a[3:0] +: 8] = b;
            dm.mem[wi] = w;
        end
    endtask
    task load_file(input string name, input [31:0] base, output integer cnt);
        begin
            fd = $fopen({dir, "/", name}, "rb");
            if (fd == 0) begin $display("FAIL cannot open %s/%s", dir, name); $finish; end
            cnt = $fread(filebuf, fd);
            $fclose(fd);
            for (i = 0; i < cnt; i = i + 1) put_ddr(base + i, filebuf[i]);
        end
    endtask

    // ---------------------------------------------------------------- the 68k bus monitor (p68k)
    integer p_reads = 0, p_bad = 0, p_sys = 0, p_p1 = 0;
    reg chk_done = 0, chk_seen = 0;
    integer chk_n = 0;
    wire [23:1] a68 = dut.core.M68K_ADDR;
    wire [23:0] a68b = {a68, 1'b0};
    wire        nas = dut.core.nAS, nu = dut.core.nUDS, nl = dut.core.nLDS, rw = dut.core.M68K_RW, ndt = dut.core.nDTACK_ADJ;
    wire [15:0] d68 = dut.core.M68K_DATA;
    reg [31:0] vaddr;
    reg [15:0] expw;
    always @(posedge dut.clk48) begin
        if (!nas && rw && !ndt && chk_n < 14 && !chk_seen) begin chk_seen <= 1; chk_n = chk_n + 1; $display("  68k read %0d: address %06x data %04x (uds %b lds %b)", chk_n, a68b, d68, !nu, !nl); end
        if (nas) chk_seen <= 0;
        if (nas) chk_done <= 1'b0;
        else if (!chk_done && rw && !ndt) begin
            chk_done <= 1'b1;
            if (a68b < 24'h000080) begin vaddr = a68b; p_sys = p_sys + 1; end
            else if (a68b < 24'h100000) begin vaddr = 32'h200000 + a68b; p_p1 = p_p1 + 1; end
            else if (a68b >= 24'hC00000 && a68b < 24'hC20000) begin vaddr = a68b - 24'hC00000; p_sys = p_sys + 1; end
            else vaddr = 32'hFFFFFFFF;
            if (vaddr != 32'hFFFFFFFF) begin
                expw = {vspace[vaddr + 1], vspace[vaddr]};          // the image holds the 68k's words byte swapped (MAME's ROM_LOAD16_WORD_SWAP)
                p_reads = p_reads + 1;
                if ((!nu && d68[15:8] != expw[15:8]) || (!nl && d68[7:0] != expw[7:0])) begin
                    p_bad = p_bad + 1;
                    if (p_bad < 6) $display("  p68k: address %06x read %04x (uds %b lds %b), the image has %04x", a68b, d68, !nu, !nl, expw);
                end
            end
        end
    end

    // ---------------------------------------------------------------- when the machine uses the words it asked for (machine clocks = clk48 clocks the enables ran)
    integer st_hold_total = 0;
    always @(posedge dut.clk48) if (dut.core.stall_r) st_hold_total = st_hold_total + 1;
    integer mcyc = 0, c_t0 = 0, s_t0 = 0, c_min = 1000, c_max = 0, s_min = 1000, s_max = 0, c_n = 0, s_n = 0;
    reg c_arm = 0, s_arm = 0, pq1 = 1, pq2 = 1;
    always @(posedge dut.clk48) begin
        if (!dut.core.stall_r) mcyc = mcyc + 1;
        pq1 <= dut.core.PCK1; pq2 <= dut.core.PCK2;
        if (dut.running && pq1 && !dut.core.PCK1) begin c_arm = 1; c_t0 = mcyc; end
        if (dut.running && pq2 && !dut.core.PCK2) begin s_arm = 1; s_t0 = mcyc; end
        if (c_arm && dut.core.LOAD && dut.core.CLK_EN_12M_N) begin
            c_arm = 0; c_n = c_n + 1;
            if (mcyc - c_t0 < c_min) c_min = mcyc - c_t0;
            if (mcyc - c_t0 > c_max) c_max = mcyc - c_t0;
        end
        if (s_arm && dut.core.CLK_EN_1HB) begin
            s_arm = 0; s_n = s_n + 1;
            if (mcyc - s_t0 < s_min) s_min = mcyc - s_t0;
            if (mcyc - s_t0 > s_max) s_max = mcyc - s_t0;
        end
    end

    // ---------------------------------------------------------------- resets of the machine after it ran (the watchdog: eight frames without a kick), and 68k restarts
    integer rs_n = 0;
    reg rs_q = 1'b1;
    always @(posedge dut.clk48) begin
        rs_q <= dut.core.nRESET;
        if (rs_q && !dut.core.nRESET) rs_n = rs_n + 1;
    end

    // ---------------------------------------------------------------- the machine age at which the stage register hands a word over (the same for every word, whatever the memory did)
    integer ap_hist [0:15];
    initial begin : aph integer hh; for (hh = 0; hh < 16; hh = hh + 1) ap_hist[hh] = 0; end
    integer ap_c_min = 1000, ap_c_max = 0, ap_s_min = 1000, ap_s_max = 0, ap_c_n = 0, ap_s_n = 0;
    always @(posedge dut.clk48) begin
        if (dut.core.MUX.c_apply) begin
            ap_c_n = ap_c_n + 1;
            ap_hist[dut.core.MUX.c_age > 15 ? 15 : dut.core.MUX.c_age] = ap_hist[dut.core.MUX.c_age > 15 ? 15 : dut.core.MUX.c_age] + 1;
            if (dut.core.MUX.c_age < ap_c_min) ap_c_min = dut.core.MUX.c_age;
            if (dut.core.MUX.c_age > ap_c_max) ap_c_max = dut.core.MUX.c_age;
        end
        if (dut.core.MUX.s_apply) begin
            ap_s_n = ap_s_n + 1;
            if (dut.core.MUX.s_age < ap_s_min) ap_s_min = dut.core.MUX.s_age;
            if (dut.core.MUX.s_age > ap_s_max) ap_s_max = dut.core.MUX.s_age;
        end
    end

    // ---------------------------------------------------------------- the sound the host gets (mclk, signed 24 bit): the largest value and the number of samples that differ from the one before
    integer a_max = 0, a_chg = 0, a_n = 0, ya_max = 0;
    reg signed [23:0] a_prev = 24'sd0;
    always @(posedge mclk) begin
        a_n = a_n + 1;
        if (audio_l != a_prev) a_chg = a_chg + 1;
        a_prev <= audio_l;
        if (audio_l > a_max) a_max = audio_l;
        if (-audio_l > a_max) a_max = -audio_l;
    end
    integer ya_chg = 0;
    reg [15:0] ya_prev = 16'd0;
    integer z_en = 0, z_wr = 0, z_rd = 0, z_adr = 0, z_io = 0;
    reg [15:0] z_la = 16'hFFFF;
    always @(posedge dut.clk48) begin
        ya_prev <= dut.snd_l;
        if (dut.snd_l != ya_prev) ya_chg = ya_chg + 1;
        if (dut.core.CLK_EN_4M_P) z_en = z_en + 1;
        if (dut.core.SDA != z_la) begin z_la <= dut.core.SDA; z_adr = z_adr + 1; end
        if (!dut.core.nIORQ && !dut.core.Z80_nSDWR) z_io = z_io + 1;
        if (!dut.core.n2610CS && !dut.core.n2610WR) z_wr = z_wr + 1;
        if ($signed(dut.snd_l) > ya_max) ya_max = $signed(dut.snd_l);
        if (-$signed(dut.snd_l) > ya_max) ya_max = -$signed(dut.snd_l);
    end

    // ---------------------------------------------------------------- lead probe (T143 3b): how long the sprite / fix address is in the LSPC's registers before NEO-273 latches it, and whether the latch is what the registers said
    wire [23:0] cand = dut.core.TRX_C_CAND;
    wire [15:0] fcand = dut.core.TRX_S_CAND;
    reg [23:0] cand_q = 24'd0, cand_lat = 24'd0;
    reg [15:0] fcand_q = 16'd0, fcand_lat = 16'd0;
    reg lat_chk = 1'b0, flat_chk = 1'b0;
    integer cand_since = 0, fcand_since = 0, lead_hist [0:8], fl_hist [0:8], lead_n = 0, lead_mis = 0, lead_min = 100000, fl_n = 0, fl_mis = 0, fl_min = 100000;
    initial begin : lh integer k; for (k = 0; k < 9; k = k + 1) begin lead_hist[k] = 0; fl_hist[k] = 0; end end
    always @(posedge dut.clk48) if (!dut.core.stall_r) begin
        cand_q <= cand; fcand_q <= fcand;
        if (cand != cand_q) cand_since = mcyc;
        if ({fcand[15:4], fcand[2:0]} != {fcand_q[15:4], fcand_q[2:0]}) fcand_since = mcyc;
        lat_chk <= 1'b0; flat_chk <= 1'b0;
        if (lat_chk) begin
            lead_n = lead_n + 1;
            if ({dut.core.C_LATCH_EXT, dut.core.C_LATCH} != cand_lat) lead_mis = lead_mis + 1;
        end
        if (flat_chk) begin
            fl_n = fl_n + 1;
            if ({dut.core.S_LATCH[15:4], dut.core.S_LATCH[2:0]} != {fcand_lat[15:4], fcand_lat[2:0]}) fl_mis = fl_mis + 1;
        end
        if (dut.running && dut.core.PCK1_EN_N) begin
            cand_lat <= cand; lat_chk <= 1'b1;
            if (mcyc - cand_since < lead_min) lead_min = mcyc - cand_since;
            lead_hist[(mcyc - cand_since) / 8 > 8 ? 8 : (mcyc - cand_since) / 8] = lead_hist[(mcyc - cand_since) / 8 > 8 ? 8 : (mcyc - cand_since) / 8] + 1;
        end
        if (dut.running && dut.core.PCK2_EN_N) begin
            fcand_lat <= fcand; flat_chk <= 1'b1;
            if (mcyc - fcand_since < fl_min) fl_min = mcyc - fcand_since;
            fl_hist[(mcyc - fcand_since) / 8 > 8 ? 8 : (mcyc - fcand_since) / 8] = fl_hist[(mcyc - fcand_since) / 8 > 8 ? 8 : (mcyc - fcand_since) / 8] + 1;
        end
    end

    // ---------------------------------------------------------------- the picture
    function [15:0] rgb565_of(input [15:0] p);                // neogeo.sv's DAC: the dark bit, 6 bit per channel to 8, then RGB565
        reg [6:0] r6, g6, b6;
        reg [7:0] r8, g8, b8;
        begin
            r6 = {1'b0, p[11:8], p[14], p[11]} - p[15];
            g6 = {1'b0, p[7:4], p[13], p[7]} - p[15];
            b6 = {1'b0, p[3:0], p[12], p[3]} - p[15];
            r8 = r6[6] ? 8'd0 : {r6[5:0], r6[4:3]};
            g8 = g6[6] ? 8'd0 : {g6[5:0], g6[4:3]};
            b8 = b6[6] ? 8'd0 : {b6[5:0], b6[4:3]};
            rgb565_of = {r8[7:3], g8[7:2], b8[7:3]};
        end
    endfunction
    reg [31:0] hash;
    integer dump_fd = 0;
    string dump_name;
    integer bd_n, other_n;
    reg [15:0] px, backdrop565;
    reg [7:0] fl, sq;
    reg [31:0] fbb;
    task read_frame;
        integer x, y;
        reg [31:0] ba;
        reg [127:0] w;
        begin
            cw_rd(17'h0C0, fl);
            fbb = FB_BASE + (fl[1:0] * FB_STRIDE);
            hash = 32'h811C9DC5; bd_n = 0; other_n = 0;
            for (y = 0; y < 224; y = y + 1)
                for (x = 0; x < 320; x = x + 1) begin
                    ba = fbb + (y * 320 + x) * 2;
                    w = dm.mem[(ba - DDR_BASE) >> 4];
                    px = w[8 * ba[3:0] +: 16];
                    if (dump_fd != 0) $fwrite(dump_fd, "%04x\n", px);
                    hash = (hash ^ {16'd0, px}) * 32'h01000193;
                    if (px == backdrop565) bd_n = bd_n + 1; else other_n = other_n + 1;
                end
        end
    endtask

    // ---------------------------------------------------------------- the run
    integer ms = 100, bdw, mcyc_target = 0;
    reg [31:0] v32;
    string mode;
    reg real_mode = 0;
    integer next_prog = 0, real_cstart = 4, dump_every = 0, next_dump = 0, dump_k = 0;
    reg [31:0] real_cmask = 32'h00FFFFFF;
    string dump_dir;
    integer frames_seen;
    reg [7:0] seq0, seq1;
    integer cnt;
    initial begin
        if (!$value$plusargs("MODE=%s", mode)) mode = "video";
        if (!$value$plusargs("DIR=%s", dir)) dir = "build/img";
        if (!$value$plusargs("MS=%d", ms)) ms = 100;
        if ($value$plusargs("MCYC=%d", mcyc_target)) ;              // run until the machine has had that many clocks (a held machine runs the same program, later)
        real_mode = $test$plusargs("REAL");
        if (real_mode) begin
            V1_BASE = 32'h03000000; V2_BASE = 32'h03400000; M1_BASE = 32'h03800000; IMG_BASE = 32'h03900000; FB_BASE = 32'h03A00000;
            if (!$value$plusargs("CSTART=%d", real_cstart)) real_cstart = 4;
            if (!$value$plusargs("CMASK=%h", real_cmask)) real_cmask = 32'h00FFFFFF;
            if (!$value$plusargs("DUMPEVERY=%d", dump_every)) dump_every = 0;
            if (!$value$plusargs("DUMPDIR=%s", dump_dir)) dump_dir = ".";
            bdw = 0;
        end else begin
        // the expected backdrop
        fd = $fopen({dir, "/expect.txt"}, "r");
        n = $fscanf(fd, "backdrop_word %h\n", bdw);
        $fclose(fd);
        end
        backdrop565 = rgb565_of(bdw[15:0]);
        // the images, as the application puts them: the ROM space, the LO ROM, the Z80 program and the samples, all in the DDR2
        load_file("vspace.bin", ROM_BASE, cnt);
        if (!real_mode) for (i = 0; i < cnt; i = i + 1) vspace[i] = filebuf[i];
        load_file("lo.bin", IMG_BASE, cnt);
        load_file("m1.bin", M1_BASE, cnt);
        if (!real_mode) load_file("v1.bin", V1_BASE, cnt);
        #200 sys_rst = 0; ui_rst = 0;
        repeat (20) @(posedge cpu_clk);
        cw_wr(17'h0A0, 8'h01);                                  // CTRL: the reset is held
        cw_wr(17'h0A1, real_mode ? 8'h01 : 8'h00);              // SYSTEM: AES, NTSC, card plugged (REAL: MVS, for sp-s2.sp1)
        cw_wr32(17'h0A8, 32'h00000000);                         // CFG: no chip
        cw_wr32(17'h0C4, FB_BASE); cw_wr32(17'h0C8, FB_STRIDE);
        cw_wr32(17'h0D0, ROM_BASE); cw_wr32(17'h0D4, V1_BASE); cw_wr32(17'h0D8, V2_BASE); cw_wr32(17'h0DC, M1_BASE); cw_wr32(17'h0E0, IMG_BASE);
        cw_wr32(17'h100, 32'h0);                                // P2ROM_MASK
        cw_wr32(17'h104, real_mode ? real_cmask : 32'h000FFFFF);   // CROM_MASK: 1 MB
        cw_wr32(17'h108, real_mode ? 32'h003FFFFF : 32'h0000FFFF);   // V1ROM_MASK
        cw_wr32(17'h10C, 32'h0);
        cw_wr32(17'h110, 32'h0001FFFF);                         // MROM_MASK
        cw_wr(17'h114, real_mode ? real_cstart[7:0] : 8'd3);    // CROM_START: the C ROM at 3 MB
        if ($value$plusargs("CDL=%d", i)) cw_wr(17'h118, i[7:0]);     // the deadlines of the stall (sweep)
        if ($value$plusargs("SDL=%d", i)) cw_wr(17'h119, i[7:0]);
        // LO ROM from the DDR2 into its block RAM
        cw_wr(17'h0E4, 8'h00);                                  // MV_CMD: load, image 0
        cw_wr(17'h0E5, 8'h01);                                  // MV_GO
        seq0 = 8'd0;
        for (i = 0; i < 400 && seq0 !== 8'd1; i = i + 1) begin   // 4096 lines of 16 bytes: about 3.5 ms
            repeat (5000) @(posedge cpu_clk);
            cw_rd(17'h0E6, seq0);
        end
        if (seq0 !== 8'd1) begin
            $display("FAIL the LO ROM move did not finish (done %0d)", seq0);
            $display("  mem: ms=%0d es=%0d m_rd_req=%b e_en=%b e_rdy=%b mg_s=%b mv_cmd=%h go_tgl=%b done_tgl=%b ui_rst=%b e_who=%0d", dut.mem.ms, dut.mem.es, dut.mem.m_rd_req, dut.mem.e_en, e_rdy,
                     dut.mem.mg_s, dut.mem.mv_cmd, dut.mem.mv_go_tgl, dut.mem.mv_done_tgl, dut.mem.ui_rst, dut.mem.e_who);
            $display("  ddr2 model: q_wr=%0d q_rd=%0d reads=%0d writes=%0d cyc=%0d last_due=%0d c_en=%b c_rdy=%b tq=%0d", dm.q_wr, dm.q_rd, dm.reads, dm.writes, dm.cyc, dm.last_due, c_en, c_rdy, dut.mem.tq_n);
            $display("  ddr2 model: e reads %0d, e_en high %0d clocks, blocked by c_en %0d clocks", dm.e_reads, dm.e_en_cyc, dm.e_blocked);
            $display("  regs: mvc=%h ctrl=%h cmds %0d %0d, va_p %b vb_p %b mz_p %b bk_p %b pw_en %b", dut.regs.mvc_r, dut.regs.ctrl_r, dut.mem.st_c_cmds, dut.mem.st_e_cmds, dut.mem.va_p, dut.mem.vb_p, dut.mem.mz_p, dut.mem.bk_p, dut.mem.pw_en);
            $finish;
        end
        cw_wr(17'h0A0, 8'h00);                                  // CTRL: run
        // run
        fork
            begin : runner
                integer t;
                for (t = 0; t < ms * 10 && !(mcyc_target != 0 && mcyc >= mcyc_target); t = t + 1) begin
                    #100000;                                    // 0.1 ms
                    if (real_mode && mcyc >= next_prog + 5000000) begin
                        next_prog = mcyc;
                        $display("  progress: machine clock %0d, 68k address %h, Z80 address %h, nRESET %b, watchdog resets %0d, stall %0d", mcyc, {dut.core.M68K_ADDR, 1'b0}, dut.core.SDA, dut.core.nRESET, rs_n, dut.core.st_stall_clk);
                    end
                    if (dump_every != 0 && mcyc >= next_dump + dump_every) begin
                        next_dump = mcyc;
                        dump_fd = $fopen($sformatf("%0s/frame_%03d.txt", dump_dir, dump_k), "w");
                        read_frame;
                        $fclose(dump_fd); dump_fd = 0;
                        $display("  frame %0d dumped at machine clock %0d (%0d backdrop-free pixels)", dump_k, mcyc, other_n);
                        dump_k = dump_k + 1;
                    end
                end
            end
        join
        if (mode == "audio") begin
            $display("  audio: the YM2610 mix reached %0d (peak, 16 bit), the host gets peak %0d in %0d samples, %0d of them different from the one before; the YM mix changed %0d times", ya_max, a_max, a_n, a_chg, ya_chg);
            $display("  z80: 4M enables %0d, address changes %0d, io writes %0d, ym writes %0d, nRESET %b, aud.mute %b sl %0d cnt %0d", z_en, z_adr, z_io, z_wr, dut.core.nRESET, dut.aud.mute, dut.aud.sl, dut.aud.cnt);
            $display("  z80: PC bus A %h, m1 reads %0d (misses %0d), nWAIT %b", dut.core.SDA, dut.mem.st_mz_miss + 0, dut.mem.st_mz_miss, dut.core.Z80_nWAIT);
            if (a_max > 1000 && a_chg > 20) $display("PASS audio"); else $display("FAIL audio");
        end else if (mode == "p68k") begin
            $display("  machine: running %b nRESET %b stall %b pm req/ack %b %b c_pend %b stall_clk %0d p_reads %0d", running, dut.core.nRESET, dut.core.stall, dut.core.MUX.pm_req_tgl, dut.core.MUX.pm_ack_tgl, dut.core.MUX.c_pend, dut.core.st_stall_clk, dut.core.st_p_reads);
            $display("  neo_mem c side: c_s %b c_t %b c_p %b tq_w %0d tq_r %0d c_en %b; model q_wr %0d q_rd %0d reads %0d cyc %0d; mux c_req %b c_seen %b c_ack_s %b c_age %0d", dut.mem.c_s, dut.mem.c_t, dut.mem.c_p, dut.mem.tq_w, dut.mem.tq_r, dut.mem.c_en, dm.q_wr, dm.q_rd, dm.reads, dm.cyc,
                     dut.core.MUX.c_req_tgl, dut.core.MUX.c_seen, dut.core.MUX.c_ack_s, dut.core.MUX.c_age);
            $display("  model head: due %0d (cyc %0d) who %b; last_due %0d; mux c_age %0d", dm.q_due[dm.q_rd % 32], dm.cyc, dm.q_who[dm.q_rd % 32], dm.last_due, dut.core.MUX.c_age);
            $display("  p68k: %0d reads checked (%0d system ROM, %0d cartridge), %0d wrong", p_reads, p_sys, p_p1, p_bad);
            if (p_bad == 0 && p_sys > 50 && p_p1 > 50) $display("PASS p68k"); else $display("FAIL p68k");
        end else begin
            if ($value$plusargs("DUMP=%s", dump_name)) dump_fd = $fopen(dump_name, "w");
            read_frame;
            if (dump_fd != 0) $fclose(dump_fd);
            cw_rd(17'h0C1, sq);
            $display("  video: frame sequence %0d, backdrop pixels %0d, other pixels %0d, hash %08x (backdrop %04x)", sq, bd_n, other_n, hash, backdrop565);
            $display("HASH %08x", hash);
            $display("  sprite address: %0d latches, %0d differ from the LSPC registers of the same clock, in the registers %0d machine clocks at least before the latch; lead in 8 clock buckets (0-7 .. 64+): %0d %0d %0d %0d %0d %0d %0d %0d %0d", lead_n, lead_mis, lead_min, lead_hist[0], lead_hist[1], lead_hist[2], lead_hist[3], lead_hist[4], lead_hist[5], lead_hist[6], lead_hist[7], lead_hist[8]);
            $display("  fix address:    %0d latches, %0d differ, at least %0d clocks before; buckets: %0d %0d %0d %0d %0d %0d %0d %0d %0d", fl_n, fl_mis, fl_min, fl_hist[0], fl_hist[1], fl_hist[2], fl_hist[3], fl_hist[4], fl_hist[5], fl_hist[6], fl_hist[7], fl_hist[8]);
            $display("  machine resets (nRESET falling): %0d", rs_n);
            $display("  hand-over age histogram (sprite) 0..15: %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d", ap_hist[0], ap_hist[1], ap_hist[2], ap_hist[3], ap_hist[4], ap_hist[5], ap_hist[6], ap_hist[7], ap_hist[8], ap_hist[9], ap_hist[10], ap_hist[11], ap_hist[12], ap_hist[13], ap_hist[14], ap_hist[15]);
            $display("  hand-over age: sprite words %0d..%0d (%0d times), fix words %0d..%0d (%0d times)", ap_c_min, ap_c_max, ap_c_n, ap_s_min, ap_s_max, ap_s_n);
            $display("  the machine's own timing: a sprite word is first used %0d..%0d machine clocks after PCK1 falls (%0d times), a fix word %0d..%0d after PCK2 (%0d times)", c_min, c_max, c_n, s_min, s_max, s_n);
            cw_rd32(17'h0B0, v32); $display("  stall clocks %0d", v32);
            cw_rd32(17'h0B4, v32); $display("  late sprite words %0d", v32);
            cw_rd32(17'h0B8, v32); $display("  late fix words %0d", v32);
            cw_rd32(17'h0BC, v32); $display("  68k reads asked %0d", v32);
            $display("  line caches (demands answered from a valid line / from a line in flight / asked of the DDR2; hints that took a line):");
            cw_rd32(17'h150, v32); $display("    sprites  hit %0d", v32);   cw_rd32(17'h154, v32); $display("             pend %0d", v32);   cw_rd32(17'h158, v32); $display("             miss %0d", v32);   cw_rd32(17'h15C, v32); $display("             hints %0d", v32);
            cw_rd32(17'h160, v32); $display("    fix      hit %0d", v32);   cw_rd32(17'h164, v32); $display("             pend %0d", v32);   cw_rd32(17'h168, v32); $display("             miss %0d", v32);   cw_rd32(17'h16C, v32); $display("             hints %0d", v32);
            cw_rd32(17'h170, v32); $display("    68k      hit %0d", v32);   cw_rd32(17'h174, v32); $display("             pend %0d", v32);   cw_rd32(17'h178, v32); $display("             miss %0d", v32);
            cw_rd32(17'h0B0, v32); $display("  machine speed: %0d machine clocks, %0d held by the stall: the machine ran at %0d.%0d%% of its speed", mcyc, v32, (100 * mcyc) / (mcyc + v32), ((1000 * mcyc) / (mcyc + v32)) % 10);
            cw_rd(17'h131, seq0); $display("  longest wait for a sprite word %0d clocks, ", seq0);
            cw_rd(17'h132, seq0); $display("  longest wait for a fix word %0d clocks", seq0);
            cw_rd(17'h130, seq0); $display("  longest c_* read %0d ui clocks", seq0);
            if (sq >= 6 && bd_n > 1000 && other_n > 500) $display("PASS video"); else $display("FAIL video");
        end
        $finish;
    end
endmodule
